<?php declare(strict_types=1); namespace Codejitsu\Ai\Console; use Codejitsu\Ai\Tools\ToolCall; use Codejitsu\Console\TerminalQuestioner;
final class TerminalConversationIO implements ConversationIO { private TerminalQuestioner $questions; public function __construct(?TerminalQuestioner $q=null){$this->questions=$q??new TerminalQuestioner();} public function ask(string $p):string{return $this->questions->ask($p);} public function select(string $p,array $c):string{return $this->questions->select($p,$c);} public function write(string $m):void{fwrite(STDOUT,$m);} public function confirmTool(ToolCall $c):bool{return strtolower($this->ask(sprintf('Allow consequential tool %s? [y/N] ',$c->tool->name)))==='y';} }
